// План specs/dashboard.md 3.3 (кейс DB-11). Десктоп 1440, admin, компания «test». Только просмотр (@prod-safe).
// Смена периода: значения обновляются через 250–450 мс после выбора — ждём ответ RPC и строки, без таймаутов.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import {
  PERIOD_LABEL, RANGE_OPTION, chooseRange, expectRowsMatchRpc, openDashboardTeam, openRangeMenu, teamWidget, trackDashboardRpc,
} from './team-performance-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд, Team Performance: выбор периода (#5814749d)', () => {
  test('Desktop Team Performance EN: "…" menu offers Last 7/14/30/90 Days and a calendar; choosing a period updates label and rows from RPC #5814749d @desktop @prod-safe', async ({ page }) => {
    const rpc = trackDashboardRpc(page);
    await openDashboardTeam(page, 'en');
    const first = await rpc.teamFor(30);
    const today = await page.evaluate(() => {
      const d = new Date();
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    });
    expect(first.to, 'период заканчивается сегодня').toBe(today);

    // Меню «…» (aria «Select range»): 4 готовых периода + календарь диапазона (комментарий программиста).
    const widget = teamWidget(page, 'en');
    const pop = await openRangeMenu(page, widget, 'en');
    for (const d of [7, 14, 30, 90]) {
      await expect(pop.getByRole('button', { name: RANGE_OPTION.en(d), exact: true })).toBeVisible();
    }
    await expect(pop.getByRole('grid')).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(pop).toBeHidden();

    // Каждый период: запрос RPC ровно за N дней по сегодня, подпись «Last N days», строки = ответ.
    for (const d of [7, 90, 14, 30]) {
      await chooseRange(page, widget, 'en', d, 'team');
      const call = await rpc.teamFor(d);
      expect(call.to).toBe(today);
      await expect(widget.getByText(PERIOD_LABEL.en(d), { exact: true })).toBeVisible();
      await expectRowsMatchRpc(page, 'en', call);
    }
  });
});
